data class Expense(val category: String, val amount: Double)
sealed interface SaveResult {
    data class Saved(val value: Expense) : SaveResult
    data class Rejected(val problems: List<String>) : SaveResult
}
fun describe(result: SaveResult) = when (result) {
    is SaveResult.Saved -> "Saved £${result.value.amount}"
    is SaveResult.Rejected -> result.problems.joinToString()
}
fun main() { println(describe(SaveResult.Rejected(listOf("Amount required")))) }
